    List<Uint8List> slicedImagesBytes = [];

    // Define the regions for the four slices
    final List<Rect> regions = [
      Rect.fromLTWH(0, 0, centerX, centerY),        // Top-left
      Rect.fromLTWH(centerX, 0, centerX, centerY),  // Top-right
      Rect.fromLTWH(0, centerY, centerX, centerY),  // Bottom-left
      Rect.fromLTWH(centerX, centerY, centerX, centerY), // Bottom-right
    ];

    // Create a new picture recorder for each slice
    for (var region in regions) {
      final recorder = ui.PictureRecorder();
      final canvas = ui.Canvas(recorder);

      // Draw the region of the original image onto the canvas
      canvas.drawImageRect(
        image,
        region,
        Rect.fromLTWH(0, 0, region.width, region.height),
        ui.Paint(),
      );

      // Convert the recorded picture to an image
      final slicedImage = await recorder.endRecording().toImage(region.width.toInt(), region.height.toInt());

      // Convert the image to bytes
      final byteData = await slicedImage.toByteData(format: ui.ImageByteFormat.png);
      if (byteData != null) {
