```csharp
using System;
using System.Drawing;
using System.Drawing.Imaging;
using System.IO;

public class ImageCompressor
{
    public static byte[] CompressImage(Image image, ImageFormat format, int quality)
    {
        if (image == null)
            throw new ArgumentNullException(nameof(image));

        if (format != ImageFormat.Png && format != ImageFormat.Jpeg)
            throw new ArgumentException("Unsupported image format. Only PNG and JPEG are supported.", nameof(format));

        if (quality < 0 || quality > 100)
            throw new ArgumentOutOfRangeException(nameof(quality), "Quality must be between 0 and 100.");

        using (var ms = new MemoryStream())
        {
            if (format == ImageFormat.Jpeg)
            {
                // Set up JPEG encoder parameters
                var encoderParameters = new EncoderParameters(1);
                encoderParameters.Param[0] = new EncoderParameter(Encoder.Quality, quality);

                // Get the JPEG encoder
                var jpegEncoder = GetEncoder(ImageFormat.Jpeg);

                // Save the image with the specified quality
                image.Save(ms, jpegEncoder, encoderParameters);
            }
            else
            {
                // Save the image in PNG format
                image.Save(ms, format);
            }

            return ms.ToArray();
        }
    }

    private static ImageCodecInfo GetEncoder(ImageFormat format)
    {
        foreach (var codec in ImageCodecInfo.GetImageDecoders())
        {
            if (codec.FormatID == format.Guid)
                return codec;
        }
        throw new ArgumentException("Unsupported image format.", nameof(format));
    }
}
```

### Explanation:

1. **Method Signature**:
   - `CompressImage(Image image, ImageFormat format, int quality)`: This method takes an `Image` object, an `ImageFormat` (either PNG or JPEG), and a quality parameter (for JPEG).

2. **Input Validation**:
   - The method checks if the input image is not null.
   - It ensures that the format is either PNG or JPEG.
   - It validates the quality parameter to be between 0 and 100.

3. **Memory Stream**:
   - A `MemoryStream` is used to store the compressed image data.

4. **JPEG Compression**:
   - For JPEG format, an `EncoderParameters` object is created to set the quality.
   - The JPEG encoder is retrieved using the `GetEncoder` method.
   - The image is saved to the memory stream with the specified quality.

5. **PNG Compression**:
   - For PNG format, the image is saved directly to the memory stream without additional parameters.

6. **GetEncoder Method**:
   - This helper method retrieves the appropriate `ImageCodecInfo` for the given image format.

7. **Return Value**:
   - The method returns the byte array containing the compressed image data.

### Usage Example:

```csharp
