### Explanation of PNG Compression Levels

PNG compression levels impact the balance between file size and compression time. Higher compression levels result in smaller file sizes but take longer to compress. Lower compression levels produce larger files but compress faster. Here's a brief overview of the `PngCompressionLevel` enum:

- `Level0`: No compression.
- `Level1`: Fastest compression with larger file size.
- `Level2` to `Level8`: Increasing levels of compression, trading off compression time for file size reduction.
- `Level9`: Maximum compression, slowest but smallest file size.

### Updated Code Using Only `ImageSharp`

Here is the updated C# method that uses only `ImageSharp` for both JPEG and PNG compression:

```csharp
using System;
using System.IO;
using SixLabors.ImageSharp;
using SixLabors.ImageSharp.Formats.Jpeg;
using SixLabors.ImageSharp.Formats.Png;
using SixLabors.ImageSharp.Processing;

public class ImageCompressor
{
    public static byte[] CompressImage(string imagePath, ImageFormat format, int quality, int? width = null, int? height = null)
    {
        if (string.IsNullOrEmpty(imagePath))
            throw new ArgumentNullException(nameof(imagePath));

        if (format != ImageFormat.Png && format != ImageFormat.Jpeg)
            throw new ArgumentException("Unsupported image format. Only PNG and JPEG are supported.", nameof(format));

        if (quality < 0 || quality > 100)
            throw new ArgumentOutOfRangeException(nameof(quality), "Quality must be between 0 and 100.");

        using (var image = Image.Load(imagePath))
        {
            // Resize the image if width or height is provided
            if (width.HasValue || height.HasValue)
            {
                image.Mutate(x => x.Resize(width ?? image.Width, height ?? image.Height));
            }

            using (var ms = new MemoryStream())
            {
                if (format == ImageFormat.Jpeg)
                {
                    // Set up JPEG encoder parameters
                    var jpegEncoder = new JpegEncoder
                    {
                        Quality = quality
                    };

                    // Save the image with the specified quality
                    image.SaveAsJpeg(ms, jpegEncoder);
                }
                else
                {
                    // Set up PNG encoder parameters
                    var pngEncoder = new PngEncoder
                    {
                        CompressionLevel = qualityToCompressionLevel(quality)
                    };

                    // Save the image in PNG format
                    image.SaveAsPng(ms, pngEncoder);
                }

                return ms.ToArray();
            }
        }
    }

    private static PngCompressionLevel qualityToCompressionLevel(int quality)
    {
        // Map quality to compression level
        if (quality >= 90)
            return PngCompressionLevel.Level9;
        else if (quality >= 80)
            return PngCompressionLevel.Level8;
        else if (quality >= 70)
            return PngCompressionLevel.Level7;
        else if (quality >= 60)
            return PngCompressionLevel.Level6;
        else if (quality >= 50)
            return PngCompressionLevel.Level5;
        else if (quality >= 40)
            return PngCompressionLevel.Level4;
        else if (quality >= 30)
            return PngCompressionLevel.Level3;
        else if (quality >= 20)
            return PngCompressionLevel.Level2;
        else
            return PngCompressionLevel.Level1;
    }
}

// Usage Example
class Program
{
    static void Main()
    {
        // Load an image
        string imagePath = "input.jpg";

        // Compress the image to JPEG with 80% quality
        byte[] compressedJpeg = ImageCompressor.CompressImage(imagePath, ImageFormat.Jpeg, 80);
        File.WriteAllBytes("output_compressed.jpg", compressedJpeg);

        // Compress the image to PNG with 80% quality and resize to 500x500
        byte[] compressedPng = ImageCompressor.CompressImage(imagePath, ImageFormat.Png, 80, 500, 500);
        File.WriteAllBytes("output_compressed.png", compressedPng);
    }
}
```

