                    c->proc = 0;
                    if(DEBUG_SCHEDULER) {
                        printf("Process %d is done running\n", p->pid);
                    }
                }
                release(&p->lock);

                p++;
                if(p >= &proc[NPROC]) {
                    p = proc;
                }
            } while(p != highproc);
        } else {
            if(DEBUG_SCHEDULER) {
                printf("No RUNNABLE processes found\n");
            }
        }
    }
}
