// InputText.cpp
#include "InputText.h"

InputText::InputText(const std::string& initialText, unsigned int maxChars, const sf::Font& font)
    : maxChars(maxChars), isActive(false) {
    text.setFont(font);
    text.setString(initialText);
    text.setCharacterSize(24);
    text.setFillColor(sf::Color::Black);
}

void InputText::handleEvent(const sf::Event& event) {
    if (event.type == sf::Event::MouseButtonPressed) {
        sf::Vector2f mousePos = static_cast<sf::Vector2f>(sf::Mouse::getPosition(window));
        if (text.getGlobalBounds().contains(mousePos)) {
            isActive = true;
        } else {
            isActive = false;
        }
    }

    if (isActive && event.type == sf::Event::TextEntered) {
        if (event.text.unicode == 8 && text.getString().getSize() > 0) { // Backspace
            text.setString(text.getString().substring(0, text.getString().getSize() - 1));
        } else if (event.text.unicode >= 32 && text.getString().getSize() < maxChars) {
            text.setString(text.getString() + static_cast<char>(event.text.unicode));
        }
    }
}

void InputText::draw(sf::RenderTarget& target) const {
    target.draw(text);
}

std::string InputText::getText() const {
    return text.getString();
}
