#### 1. Player Rating System Class
We will create a `PlayerRating` class to manage the player ratings.

```cpp
// PlayerRating.h
#ifndef PLAYER_RATING_H
#define PLAYER_RATING_H

#include <string>
#include <map>
#include <fstream>

class PlayerRating {
public:
    void addWin(const std::string& player);
    void addLoss(const std::string& player);
    void saveToFile(const std::string& filename);
    void loadFromFile(const std::string& filename);
    std::string getRating(const std::string& player);

private:
    std::map<std::string, int> wins;
    std::map<std::string, int> losses;
    std::map<std::string, int> totalGames;
};

#endif // PLAYER_RATING_H
```

```cpp
// PlayerRating.cpp
#include "PlayerRating.h"
#include <fstream>
#include <sstream>

void PlayerRating::addWin(const std::string& player) {
    wins[player]++;
    totalGames[player]++;
}

void PlayerRating::addLoss(const std::string& player) {
    losses[player]++;
    totalGames[player]++;
}

void PlayerRating::saveToFile(const std::string& filename) {
    std::ofstream file(filename);
    for (const auto& entry : totalGames) {
        file << entry.first << " " << wins[entry.first] << " " << losses[entry.first] << " " << entry.second << "\n";
    }
    file.close();
}

void PlayerRating::loadFromFile(const std::string& filename) {
    std::ifstream file(filename);
    if (!file.is_open()) return;

    std::string line;
    while (std::getline(file, line)) {
        std::istringstream iss(line);
        std::string player;
        int win, loss, total;
        if (iss >> player >> win >> loss >> total) {
            wins[player] = win;
            losses[player] = loss;
            totalGames[player] = total;
        }
    }
    file.close();
}

std::string PlayerRating::getRating(const std::string& player) {
    if (totalGames.find(player) == totalGames.end()) return "No record found";
    return "Wins: " + std::to_string(wins[player]) + ", Losses: " + std::to_string(losses[player]) + ", Total Games: " + std::to_string(totalGames[player]);
}
