function process_artiste_form() {
    if (!isset($_POST['artiste_form_nonce']) || !wp_verify_nonce($_POST['artiste_form_nonce'], 'artiste_form_nonce')) {
        return;
    }

    if (!is_user_logged_in()) {
        return;
