### Best Practices and Features to Improve User Experience

1. **Caching**: The backend uses `lru_cache` to reduce the number of database queries.
2. **Pagination**: The frontend loads photos in smaller chunks as the user scrolls, improving performance and responsiveness.
3. **Loading Indicator**: A `ProgressBar` is shown while data is being fetched to provide visual feedback to the user.
4. **Error Handling**: Clear error messages are displayed to the user in case of network or server issues.
5. **User Feedback**: Toast messages are used to inform the user about the success or failure of actions like submitting photos and admin actions.
6. **Image Loading**: The `Glide` library is used to efficiently load images into the `ImageView`.
7. **Admin Actions**: The admin panel allows the admin to approve or reject pending photos, ensuring that only one photo per name is kept permanently.

By implementing these features and best practices, the app will be more user-friendly and efficient, ensuring a better overall user experience.

Certainly! To handle duplicate photo submissions and ensure that only one photo per name is kept permanently, we need to enhance both the backend and frontend. Here's a detailed implementation:

### Backend (Flask)

1. **Ensure Unique Names in the `photos` Table**: Use a unique constraint on the `name` column in the `photos` table.
2. **Handle Duplicates in the `pending_photos` Table**: When a photo with a duplicate name is submitted, move it to the `pending_photos` table.
3. **Admin Approval**: When an admin approves a photo, ensure that any existing photo with the same name is deleted before inserting the new photo.

Here is the updated backend code:

```python
from flask import Flask, request, jsonify
import os
import sqlite3
from functools import lru_cache

app = Flask(__name__)

# Database setup
DATABASE = 'photos.db'
CACHE_SIZE = 128  # Adjust cache size as needed

def init_db():
    conn = sqlite3.connect(DATABASE)
    c = conn.cursor()
    c.execute('''CREATE TABLE IF NOT EXISTS photos (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    name TEXT UNIQUE,
                    price REAL,
                    description TEXT,
                    photo_path TEXT
                )''')
    c.execute('''CREATE TABLE IF NOT EXISTS pending_photos (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    name TEXT,
                    price REAL,
                    description TEXT,
                    photo_path TEXT
                )''')
    conn.commit()
    conn.close()

@app.route('/submit', methods=['POST'])
def submit_photo():
    if 'photo' not in request.files:
        return jsonify({'error': 'No photo provided'}), 400

    photo = request.files['photo']
    name = request.form.get('name')
    price = request.form.get('price')
    description = request.form.get('description', '')

    if not name or not price:
        return jsonify({'error': 'Name and price are required'}), 400

    # Save the photo
    photo_path = os.path.join('uploads', photo.filename)
    photo.save(photo_path)

    # Check if a photo with the same name already exists
    conn = sqlite3.connect(DATABASE)
    c = conn.cursor()
    c.execute('SELECT * FROM photos WHERE name = ?', (name,))
    existing_photo = c.fetchone()

    if existing_photo:
        # Move the new photo to the pending_photos table
        c.execute('INSERT INTO pending_photos (name, price, description, photo_path) VALUES (?, ?, ?, ?)',
                  (name, price, description, photo_path))
        conn.commit()
        conn.close()

        return jsonify({'message': 'Photo submitted successfully. Awaiting admin approval.'})

    # Insert the new photo
    c.execute('INSERT INTO photos (name, price, description, photo_path) VALUES (?, ?, ?, ?)',
              (name, price, description, photo_path))
    conn.commit()
    conn.close()

    return jsonify({'message': 'Photo submitted successfully'})

@app.route('/search', methods=['GET'])
def search_photos():
    query = request.args.get('query')
    if not query:
        return jsonify({'error': 'Search query is required'}), 400

    conn = sqlite3.connect(DATABASE)
    c = conn.cursor()
    c.execute('SELECT * FROM photos WHERE name LIKE ? OR description LIKE ?',
              (f'%{query}%', f'%{query}%'))
    results = c.fetchall()
    conn.close()

    return jsonify(results)

@lru_cache(maxsize=CACHE_SIZE)
def get_photos(page, page_size):
    offset = (page - 1) * page_size
    conn = sqlite3.connect(DATABASE)
    c = conn.cursor()
    c.execute('SELECT * FROM photos ORDER BY price ASC, name ASC, description ASC LIMIT ? OFFSET ?',
              (page_size, offset))
    results = c.fetchall()
    conn.close()

    # Format the results to include photo URLs
    formatted_results = []
    for row in results:
        formatted_results.append({
            'id': row[0],
            'name': row[1],
            'price': row[2],
            'description': row[3],
            'photo_url': f'/uploads/{os.path.basename(row[4])}'
        })

    return formatted_results

@app.route('/list', methods=['GET'])
def list_photos():
    page = int(request.args.get('page', 1))
    page_size = int(request.args.get('page_size', 10))

    photos = get_photos(page, page_size)

    return jsonify(photos)

@app.route('/admin/pending', methods=['GET'])
def list_pending_photos():
    conn = sqlite3.connect(DATABASE)
    c = conn.cursor()
    c.execute('SELECT * FROM pending_photos')
    results = c.fetchall()
    conn.close()

    # Format the results to include photo URLs
    formatted_results = []
    for row in results:
        formatted_results.append({
            'id': row[0],
            'name': row[1],
            'price': row[2],
            'description': row[3],
            'photo_url': f'/uploads/{os.path.basename(row[4])}'
        })

    return jsonify(formatted_results)

@app.route('/admin/approve', methods=['POST'])
def approve_photo():
    photo_id = request.form.get('photo_id')
    if not photo_id:
        return jsonify({'error': 'Photo ID is required'}), 400

    conn = sqlite3.connect(DATABASE)
    c = conn.cursor()

    # Get the pending photo details
    c.execute('SELECT * FROM pending_photos WHERE id = ?', (photo_id,))
    pending_photo = c.fetchone()

    if not pending_photo:
        return jsonify({'error': 'Photo not found'}), 404

    name = pending_photo[1]

    # Check if a photo with the same name already exists
    c.execute('SELECT * FROM photos WHERE name = ?', (name,))
    existing_photo = c.fetchone()

    if existing_photo:
        # Delete the existing photo
        os.remove(existing_photo[4])
        c.execute('DELETE FROM photos WHERE id = ?', (existing_photo[0],))

    # Insert the new photo
    c.execute('INSERT INTO photos (name, price, description, photo_path) VALUES (?, ?, ?, ?)',
              (pending_photo[1], pending_photo[2], pending_photo[3], pending_photo[4]))

    # Delete the pending photo
    os.remove(pending_photo[4])
    c.execute('DELETE FROM pending_photos WHERE id = ?', (photo_id,))

    conn.commit()
    conn.close()

    # Clear the cache
    get_photos.cache_clear()

    return jsonify({'message': 'Photo approved and added successfully'})

@app.route('/admin/reject', methods=['POST'])
def reject_photo():
    photo_id = request.form.get('photo_id')
    if not photo_id:
        return jsonify({'error': 'Photo ID is required'}), 400

    conn = sqlite3.connect(DATABASE)
    c = conn.cursor()

    # Get the pending photo details
    c.execute('SELECT * FROM pending_photos WHERE id = ?', (photo_id,))
    pending_photo = c.fetchone()

    if not pending_photo:
        return jsonify({'error': 'Photo not found'}), 404

    # Delete the pending photo
    os.remove(pending_photo[4])
    c.execute('DELETE FROM pending_photos WHERE id = ?', (photo_id,))

    conn.commit()
    conn.close()

    return jsonify({'message': 'Photo rejected and removed'})

if __name__ == '__main__':
    init_db()
    app.run(debug=True)
