    n = matrix.shape[0]

    # Check if the row and column indices are within bounds
    if row >= n or col >= n:
        raise IndexError("Row or column index out of bounds.")

    # Remove the specified row and column
    minor_matrix = np.delete(matrix, row, axis=0)
    minor_matrix = np.delete(minor_matrix, col, axis=1)

    # Calculate the determinant of the resulting submatrix
    minor_value = np.linalg.det(minor_matrix)

